def metric_table(regime):
 z=summary[summary.regime==regime].set_index('method').loc[[v for v in labels if v in set(summary[summary.regime==regime].method)]].reset_index();z=z[['method']+metrics];z[metrics]*=100;z['method']=z.method.map(labels);out=table(z)
